arguments.file_text:
@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1 class="mb-3">Kanban Board</h1>

@if (isLoading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @errorMessage
        <button class="btn btn-link" @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardStatsBar TotalCount="allTasks.Count"
                   ToDoCount="ToDo.Count"
                   InProgressCount="InProgress.Count"
                   DoneCount="Done.Count"
                   OverdueCount="allTasks.Count(t => t.DueDate < DateTime.Today)" />

    <BoardSearchBar SearchTerm="@searchTerm" OnSearchChanged="HandleSearchChanged" />

    <div class="row g-3">
        <KanbanColumn ColumnName="To Do"
                      Tasks="FilteredToDo"
                      CanMoveLeft="false"
                      CanMoveRight="true"
                      OnMoveTask="args => HandleMoveTask(args.TaskId, args.Dir, \"To Do\")"
                      OnAddTask="model => HandleAddTask(model, \"To Do\")" />

        <KanbanColumn ColumnName="In Progress"
                      Tasks="FilteredInProgress"
                      CanMoveLeft="true"
                      CanMoveRight="true"
                      OnMoveTask="args => HandleMoveTask(args.TaskId, args.Dir, \"In Progress\")"
                      OnAddTask="model => HandleAddTask(model, \"In Progress\")" />

        <KanbanColumn ColumnName="Done"
                      Tasks="FilteredDone"
                      CanMoveLeft="true"
                      CanMoveRight="false"
                      OnMoveTask="args => HandleMoveTask(args.TaskId, args.Dir, \"Done\")"
                      OnAddTask="model => HandleAddTask(model, \"Done\")" />
    </div>
}

@code {
