+    private List<TaskItem> ToDo => allTasks.Where(t => t.Status == "To Do").ToList();
+    private List<TaskItem> InProgress => allTasks.Where(t => t.Status == "In Progress").ToList();
+    private List<TaskItem> Done => allTasks.Where(t => t.Status == "Done").ToList();
+
+    // Filtered column lists (used for display)
+    private List<TaskItem> FilteredToDo => ApplySearch(ToDo);
+    private List<TaskItem> FilteredInProgress => ApplySearch(InProgress);
+    private List<TaskItem> FilteredDone => ApplySearch(Done);
+
+    private List<TaskItem> ApplySearch(List<TaskItem> tasks)
+    {
+        if (string.IsNullOrWhiteSpace(searchTerm))
+            return tasks;
+        return tasks.Where(t => t.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase)).ToList();
+    }
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadTasks();
+    }
+
+    private async Task LoadTasks()
+    {
+        isLoading = true;
+        errorMessage = null;
+        try
+        {
+            allTasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private void HandleSearchChanged(string value)
+    {
+        searchTerm = value;
+    }
+
+    private async Task HandleMoveTask(int taskId, KanbanColumn.Direction direction, string currentStatus)
+    {
+        var currentIndex = Array.IndexOf(Statuses, currentStatus);
+        var newIndex = direction == KanbanColumn.Direction.Left ? currentIndex - 1 : currentIndex + 1;
+
+        if (newIndex < 0 || newIndex >= Statuses.Length)
+            return;
+
+        var newStatus = Statuses[newIndex];
+
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
+            // Update local state
+            var task = allTasks.FirstOrDefault(t => t.Id == taskId);
+            if (task is not null)
+            {
+                allTasks.Remove(task);
+                allTasks.Add(task with { Status = newStatus });
+            }
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+    }
+
+    private async Task HandleAddTask(AddTaskForm.NewTaskModel model, string status)
+    {
+        try
+        {
+            var created = await TaskService.CreateTaskAsync(model.Title, model.Assignee, model.Priority, model.DueDate);
+            // CreateTaskAsync returns the task; if status differs, the task is already in the right column
+            // since the service sets the default status. We add it with the column's status.
+            allTasks.Add(created with { Status = status });
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+    }
+}
+

